function tileAt(x,z){return state.tiles.find(t=>t.x===x&&t.z===z);}
function walkable(x,z){const tx=Math.floor((x+1)/2),tz=Math.floor((z+1)/2);if(!tileAt(tx,tz))return false;return !state.buildings.some(b=>b.type==='wall'&&b.x===tx&&b.z===tz&&Math.abs(x-tx*2)<.88&&Math.abs(z-tz*2)<.27);}
